import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Textarea } from "@/components/ui/textarea";
import { formatDate, formatMoney, fromCents, monthStartTimestamp, priorityLabel, scopeLabel, toCents } from "@/lib/finance";
import { budgetStatusLabel, budgetTypeLabel, calculateBudgetVsActual } from "@/lib/budgetVsActual";
import { trpc } from "@/lib/trpc";
import { dashboardPeriodQuery } from "@/lib/dashboardPeriod";
import { debtKindLabel } from "../../../shared/manualObligations";
import { emptyWorkspaceFilters, filterWorkspaceSnapshot, WorkspaceFilterBar } from "@/components/WorkspaceFilterBar";
import { PlanningDebtAmortizationDialog } from "@/components/PlanningDebtAmortizationDialog";
import { AlertTriangle, Archive, ArchiveRestore, CalendarCheck2, Check, ChevronRight, CircleDollarSign, ClipboardCheck, FileClock, Goal, ListTodo, Pencil, Plus, Scale, Target, Trash2, WalletCards } from "lucide-react";
import { FormEvent, useState } from "react";
import { toast } from "sonner";

type PlanningView = "budget" | "goals" | "debts" | "tasks" | "reviews" | "decisions";

const planningTabs: { value: PlanningView; label: string }[] = [
  { value: "budget", label: "Presupuesto" },
  { value: "goals", label: "Objetivos" },
  { value: "debts", label: "Deudas" },
  { value: "tasks", label: "Tareas" },
  { value: "reviews", label: "Revisiones" },
  { value: "decisions", label: "Decisiones" },
];

function PlanningEmpty({ icon: Icon, title, text, actionLabel, onAction }: { icon: typeof Target; title: string; text: string; actionLabel: string; onAction: () => void }) {
  return <div className="planning-empty"><div className="empty-icon"><Icon className="size-5" /></div><h3>{title}</h3><p>{text}</p><Button variant="outline" onClick={onAction}>{actionLabel}</Button></div>;
}

export default function Planning() {
  const { data, isLoading } = trpc.finance.dashboard.useQuery(dashboardPeriodQuery);
  const utils = trpc.useUtils();
  const [view, setView] = useState<PlanningView>("budget");
  const [dialogOpen, setDialogOpen] = useState(false);
  const [workspaceFilters, setWorkspaceFilters] = useState(emptyWorkspaceFilters);
  const refresh = async () => { await utils.finance.dashboard.invalidate(); setDialogOpen(false); };
  const currency = data?.profile?.currency ?? "MXN";
  const scopedData = data ? filterWorkspaceSnapshot(data, workspaceFilters) : null;

  if (isLoading || !data || !scopedData) return <div className="page-loading">Preparando tus planes financieros…</div>;

  const title = {
    budget: ["Presupuesto mensual", "Planifica importes y contrasta el presupuesto con tus movimientos manuales."],
    goals: ["Objetivos financieros", "Convierte prioridades en aportaciones, plazos y escenarios comprensibles."],
    debts: ["Deudas y obligaciones", "Mantén saldo, interés, vencimiento y prioridad en una sola vista."],
    tasks: ["Próximas acciones", "Gestiona tareas que llevan tus decisiones a la práctica, sin ejecutar operaciones."],
    reviews: ["Revisiones mensuales", "Cierra cada periodo con resultados, observaciones y acciones prioritarias."],
    decisions: ["Decisiones explicables", "Registra el contexto, supuestos, riesgos y alternativas de cada decisión relevante."],
  }[view];

  return <div className="space-y-7">
    <header className="page-heading"><div><p className="eyebrow">Planificación y seguimiento</p><h1>{title[0]}</h1><p>{title[1]}</p></div><Dialog open={dialogOpen} onOpenChange={setDialogOpen}><DialogTrigger asChild><Button className="btn-primary" onClick={() => setDialogOpen(true)}><Plus className="size-4" /> {view === "budget" ? "Añadir partida" : view === "goals" ? "Crear objetivo" : view === "debts" ? "Añadir deuda" : view === "tasks" ? "Crear tarea" : view === "reviews" ? "Crear revisión" : "Registrar decisión"}</Button></DialogTrigger><DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>{view === "budget" ? "Nueva partida presupuestaria" : view === "goals" ? "Nuevo objetivo" : view === "debts" ? "Nueva deuda" : view === "tasks" ? "Nueva tarea" : view === "reviews" ? "Nueva revisión mensual" : "Nueva decisión"}</DialogTitle><DialogDescription>Se guardará únicamente en tu espacio privado de Meximoney.</DialogDescription></DialogHeader>{view === "budget" && <BudgetForm categories={data.categories} entities={data.entities} projects={data.projects} onDone={refresh} />}{view === "goals" && <GoalForm currency={currency} entities={data.entities} projects={data.projects} onDone={refresh} />}{view === "debts" && <DebtForm currency={currency} entities={data.entities} projects={data.projects} onDone={refresh} />}{view === "tasks" && <TaskForm goals={data.goals} debts={data.debts} onDone={refresh} />}{view === "reviews" && <ReviewForm snapshot={data} onDone={refresh} />}{view === "decisions" && <DecisionForm onDone={refresh} />}</DialogContent></Dialog></header>
    <Tabs className="w-full min-w-0" value={view} onValueChange={value => setView(value as PlanningView)}><TabsList className="planning-tabs">{planningTabs.map(tab => <TabsTrigger key={tab.value} value={tab.value}>{tab.label}</TabsTrigger>)}</TabsList></Tabs>
    <WorkspaceFilterBar snapshot={data} filters={workspaceFilters} onChange={setWorkspaceFilters} />
    {view === "budget" && <BudgetPanel snapshot={scopedData} currency={currency} onCreate={() => setDialogOpen(true)} />}
    {view === "goals" && <GoalsPanel snapshot={scopedData} currency={currency} onCreate={() => setDialogOpen(true)} />}
    {view === "debts" && <><DebtsPanel snapshot={scopedData} currency={currency} onCreate={() => setDialogOpen(true)} /><DebtInstallmentPanel snapshot={scopedData} /></>}
    {view === "tasks" && <TasksPanel snapshot={scopedData} onCreate={() => setDialogOpen(true)} refresh={refresh} />}
    {view === "reviews" && <ReviewsPanel snapshot={scopedData} currency={currency} onCreate={() => setDialogOpen(true)} />}
    {view === "decisions" && <DecisionsPanel snapshot={scopedData} onCreate={() => setDialogOpen(true)} />}
  </div>;
}

function BudgetPanel({ snapshot, currency, onCreate }: { snapshot: any; currency: string; onCreate: () => void }) {
  const utils = trpc.useUtils(); const [mode, setMode] = useState<"cards" | "summary" | "progress">("cards"); const [editing, setEditing] = useState<any | null>(null);
  const remove = trpc.finance.budgets.remove.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); toast.success("Partida eliminada"); }, onError: error => toast.error(error.message) });
  const results = calculateBudgetVsActual(snapshot, currency).slice().sort((a, b) => new Date(b.budget.periodStart).getTime() - new Date(a.budget.periodStart).getTime());
  const refresh = async () => { await utils.finance.dashboard.invalidate(); setEditing(null); };
  const titleFor = (result: any) => result.budget.type === "savings" || result.budget.type === "investment" ? budgetTypeLabel(result.budget.type) : snapshot.categories.find((item: any) => item.id === result.budget.categoryId)?.name ?? "Sin categoría";
  return <section className="space-y-4"><div className="content-card text-sm text-muted-foreground"><strong className="text-foreground">Presupuesto vs. Real:</strong> ingresos y gastos usan movimientos aprobados; ahorro e inversión usan aportaciones manuales a posiciones. Las divisas sin conversión manual quedan fuera del total comparable.</div><section className="content-card space-y-5">{results.length === 0 ? <PlanningEmpty icon={CircleDollarSign} title="No hay partidas presupuestarias" text="Crea una partida mensual para comparar tu previsión con movimientos aprobados o aportaciones manuales." actionLabel="Crear primera partida" onAction={onCreate} /> : <><div className="flex flex-col gap-3 border-b pb-4 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="text-base font-semibold">Seguimiento mensual</h2><p className="text-sm text-muted-foreground">Elige el nivel de detalle que necesitas.</p></div><div className="flex rounded-lg bg-muted p-1"><Button size="sm" type="button" variant={mode === "cards" ? "default" : "ghost"} onClick={() => setMode("cards")}>Partidas</Button><Button size="sm" type="button" variant={mode === "summary" ? "default" : "ghost"} onClick={() => setMode("summary")}>Resumen</Button><Button size="sm" type="button" variant={mode === "progress" ? "default" : "ghost"} onClick={() => setMode("progress")}>Progreso</Button></div></div>{mode === "cards" ? <div className="budget-board">{results.map(result => { const { budget, actualCents, differenceCents } = result; return <article key={budget.id} className="budget-card"><div className="card-title-row"><div><span className={`scope-pill scope-${budget.scope}`}>{scopeLabel[budget.scope]}</span><h2 className="mt-3">{titleFor(result)}</h2><p className="capitalize">{formatDate(budget.periodStart, { month: "long", year: "numeric" })} · {budgetTypeLabel(budget.type)}</p></div><div className="flex items-start gap-1"><span className={result.status === "over_plan" ? "rounded-full bg-destructive/10 px-2 py-1 text-xs font-medium text-destructive" : "rounded-full bg-emerald-500/10 px-2 py-1 text-xs font-medium text-emerald-700"}>{budgetStatusLabel(result)}</span><Button type="button" variant="ghost" size="icon" onClick={() => setEditing(budget)} aria-label="Editar partida"><Pencil className="size-4"/></Button><button className="row-action-danger" aria-label="Eliminar partida" onClick={() => confirm("¿Eliminar esta partida presupuestaria?") && remove.mutate({ id: budget.id })}><Trash2 className="size-4" /></button></div></div><div className="budget-figures"><div><span>Previsto</span><strong>{formatMoney(budget.plannedCents, currency)}</strong></div><div><span>Real</span><strong>{formatMoney(actualCents, currency)}</strong></div></div><div className="budget-progress"><span style={{ width: `${budget.plannedCents ? Math.min(100, (actualCents / budget.plannedCents) * 100) : 0}%` }} /></div><div className="budget-footer"><span>Variación</span><b className={result.isWithinPlan ? "amount-positive" : "amount-negative"}>{differenceCents >= 0 ? "+" : "−"}{formatMoney(Math.abs(differenceCents), currency)}</b></div></article>; })}</div> : null}{mode === "summary" ? <div className="overflow-x-auto"><table className="w-full min-w-[620px] text-sm"><thead className="border-b text-left text-muted-foreground"><tr><th className="p-3">Partida</th><th className="p-3">Tipo</th><th className="p-3 text-right">Previsto</th><th className="p-3 text-right">Real</th><th className="p-3 text-right">Estado</th></tr></thead><tbody>{results.map(result => <tr key={result.budget.id} className="border-b"><td className="p-3 font-medium">{titleFor(result)}</td><td className="p-3">{budgetTypeLabel(result.budget.type)}</td><td className="p-3 text-right">{formatMoney(result.budget.plannedCents, currency)}</td><td className="p-3 text-right">{formatMoney(result.actualCents, currency)}</td><td className="p-3 text-right">{budgetStatusLabel(result)}</td></tr>)}</tbody></table></div> : null}{mode === "progress" ? <div className="space-y-4">{results.map(result => { const percent = result.budget.plannedCents ? Math.min(100, (result.actualCents / result.budget.plannedCents) * 100) : 0; return <div key={result.budget.id} className="rounded-xl border p-4"><div className="flex justify-between gap-3"><div><p className="font-medium">{titleFor(result)}</p><p className="text-xs text-muted-foreground">{budgetTypeLabel(result.budget.type)}</p></div><span className={result.status === "over_plan" ? "text-sm font-medium text-destructive" : "text-sm font-medium text-emerald-700"}>{percent.toFixed(0)}%</span></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-muted"><span className={result.status === "over_plan" ? "block h-full rounded-full bg-destructive" : "block h-full rounded-full bg-primary"} style={{ width: `${percent}%` }} /></div><div className="mt-2 flex justify-between text-xs text-muted-foreground"><span>{formatMoney(result.actualCents, currency)} real</span><span>{formatMoney(result.budget.plannedCents, currency)} previsto</span></div></div>; })}</div> : null}</>}</section><Dialog open={!!editing} onOpenChange={open => !open && setEditing(null)}><DialogContent className="max-h-[90vh] max-w-2xl overflow-y-auto"><DialogHeader><DialogTitle>Editar partida presupuestaria</DialogTitle><DialogDescription>El importe real se recalcula desde tus registros manuales.</DialogDescription></DialogHeader>{editing ? <BudgetForm budget={editing} categories={snapshot.categories} entities={snapshot.entities} projects={snapshot.projects} onDone={refresh} /> : null}</DialogContent></Dialog></section>;
}

function GoalsPanel({ snapshot, currency, onCreate }: { snapshot: any; currency: string; onCreate: () => void }) {
  const utils = trpc.useUtils();
  const [editing, setEditing] = useState<any | null>(null);
  const [showArchived, setShowArchived] = useState(false);
  const save = trpc.finance.goals.save.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); setEditing(null); toast.success("Objetivo actualizado"); }, onError: error => toast.error(error.message) });
  const activeGoals = snapshot.goals.filter((goal: any) => goal.status !== "cancelled");
  const archivedGoals = snapshot.goals.filter((goal: any) => goal.status === "cancelled");
  const payloadFor = (goal: any, status: "active" | "cancelled") => ({ id: goal.id, entityId: goal.entityId, projectId: goal.projectId, name: goal.name, type: goal.type, scope: goal.scope, targetCents: goal.targetCents, currentCents: goal.currentCents, monthlyContributionCents: goal.monthlyContributionCents, currency: goal.currency, targetDate: goal.targetDate ? new Date(goal.targetDate).getTime() : null, priority: goal.priority, status, notes: goal.notes ?? null });
  const archive = (goal: any) => { if (confirm(`¿Archivar “${goal.name}”? Sus posiciones vinculadas, aportaciones y valores se conservarán; dejará de aparecer entre los objetivos activos.`)) save.mutate(payloadFor(goal, "cancelled")); };
  const restore = (goal: any) => save.mutate(payloadFor(goal, "active"));
  return <section className="goals-layout">{activeGoals.length === 0 ? <section className="content-card"><PlanningEmpty icon={Goal} title="Sin objetivos activos" text="Crea una meta nueva o restaura un objetivo archivado. Archivar nunca borra sus posiciones o historial." actionLabel="Crear objetivo" onAction={onCreate} /></section> : activeGoals.map((goal: any) => { const linkedPositions = (snapshot.investments ?? []).filter((item: any) => item.goalId === goal.id); const activeLinkedValue = linkedPositions.filter((item: any) => item.status === "active").reduce((sum: number, item: any) => sum + item.currentValueCents, 0); const goalContributions = (snapshot.transactions ?? []).filter((transaction: any) => transaction.goalId === goal.id && (transaction.type === "income" || transaction.type === "transfer_in") && transaction.reviewStatus === "approved").sort((left: any, right: any) => new Date(right.occurredAt).getTime() - new Date(left.occurredAt).getTime()); const supportedCents = goal.currentCents + activeLinkedValue; const remaining = Math.max(0, goal.targetCents - supportedCents); const percent = goal.targetCents ? Math.min(100, (supportedCents / goal.targetCents) * 100) : 0; const months = goal.monthlyContributionCents > 0 ? Math.ceil(remaining / goal.monthlyContributionCents) : null; return <article className="content-card goal-detail-card" key={goal.id}><div className="goal-detail-top"><div><span className={`scope-pill scope-${goal.scope}`}>{scopeLabel[goal.scope]}</span><h2>{goal.name}</h2><p>{priorityLabel[goal.priority]} prioridad · {goal.targetDate ? `Meta: ${formatDate(goal.targetDate)}` : "Fecha objetivo pendiente"}</p></div><div className="flex items-center gap-1"><Button type="button" variant="ghost" size="icon" aria-label={`Editar ${goal.name}`} onClick={() => setEditing(goal)}><Pencil className="size-4" /></Button><Button type="button" size="sm" variant="outline" onClick={() => setEditing(goal)}>Editar aportaciones</Button><Button type="button" variant="ghost" size="icon" aria-label={`Archivar ${goal.name}`} onClick={() => archive(goal)}><Archive className="size-4" /></Button></div></div><div className="goal-number"><strong>{percent.toFixed(0)}%</strong><span>{formatMoney(supportedCents, goal.currency)} respaldado de {formatMoney(goal.targetCents, goal.currency)}</span></div><div className="progress-track progress-large"><span style={{ width: `${percent}%` }} /></div><div className="scenario-grid"><div><small>Falta por cubrir</small><strong>{formatMoney(remaining, goal.currency)}</strong></div><div><small>Saldo manual</small><strong>{formatMoney(goal.currentCents, goal.currency)}</strong></div><div><small>Capital vinculado</small><strong>{formatMoney(activeLinkedValue, goal.currency)}</strong></div><div><small>Escenario base</small><strong>{months === null ? "Define aportación" : `${months} meses`}</strong></div></div>{linkedPositions.length ? <div className="mt-4 rounded-xl border border-primary/15 bg-primary/5 p-3 text-sm"><p className="font-medium">Posiciones que respaldan este objetivo</p><div className="mt-2 space-y-1.5">{linkedPositions.map((position: any) => <div className="flex flex-wrap items-center justify-between gap-2" key={position.id}><a href="/inversiones" className="font-medium text-primary underline-offset-4 hover:underline">{position.name}</a><span>{position.status === "active" ? formatMoney(position.currentValueCents, position.currency) : "No incluida: posición " + (position.status === "paused" ? "en pausa" : "cerrada")}</span></div>)}</div><p className="mt-3 text-xs text-muted-foreground">El valor vinculado no modifica patrimonio ni el saldo manual. Evita registrar aquí el mismo importe que ya está en una posición vinculada.</p></div> : null}{goalContributions.length ? <div className="mt-4 rounded-xl border border-border/70 p-3 text-sm"><div className="flex flex-wrap items-center justify-between gap-2"><p className="font-medium">Aportaciones registradas</p><span className="text-xs text-muted-foreground">{goalContributions.length} movimiento{goalContributions.length === 1 ? "" : "s"}</span></div><div className="mt-2 divide-y divide-border/70">{goalContributions.slice(0, 5).map((transaction: any) => <div className="flex items-center justify-between gap-3 py-2" key={transaction.id}><div className="min-w-0"><p className="truncate font-medium">{formatMoney(transaction.amountCents, transaction.currency)}</p><p className="truncate text-xs text-muted-foreground">{formatDate(transaction.occurredAt)}{transaction.notes ? ` · ${transaction.notes}` : ""}</p></div><Button type="button" variant="ghost" size="sm" className="shrink-0 text-xs" onClick={() => setEditing(goal)}>Editar aportaciones</Button></div>)}</div><p className="mt-2 text-xs text-muted-foreground">Estas aportaciones son movimientos aprobados. El botón «Editar aportaciones» permite actualizar el saldo manual y la aportación mensual del objetivo sin duplicar movimientos.</p></div> : <p className="mt-4 rounded-lg bg-muted/50 p-3 text-xs text-muted-foreground">Aún no hay movimientos de aportación aprobados vinculados. Usa «Editar aportaciones» para ajustar los valores manuales del objetivo.</p>}{goal.notes ? <p className="goal-notes"><strong>Supuesto:</strong> {goal.notes}</p> : null}</article>; })}<section className="content-card"><button type="button" className="flex w-full items-center justify-between text-left" onClick={() => setShowArchived(!showArchived)}><span><strong>Objetivos archivados</strong><small className="ml-2 text-muted-foreground">{archivedGoals.length}</small></span><span className="text-sm text-primary">{showArchived ? "Ocultar" : "Ver archivados"}</span></button>{showArchived ? <div className="mt-4 space-y-3 border-t pt-4">{archivedGoals.length ? archivedGoals.map((goal: any) => { const linked = (snapshot.investments ?? []).filter((item: any) => item.goalId === goal.id); return <div className="flex flex-col gap-3 rounded-lg border p-3 sm:flex-row sm:items-center sm:justify-between" key={goal.id}><div><strong>{goal.name}</strong><p className="mt-1 text-sm text-muted-foreground">{formatMoney(goal.currentCents, goal.currency)} manual · {linked.length} posición{linked.length === 1 ? "" : "es"} vinculada{linked.length === 1 ? "" : "s"}</p></div><Button type="button" variant="outline" size="sm" disabled={save.isPending} onClick={() => restore(goal)}><ArchiveRestore className="mr-1.5 size-3.5" />Restaurar</Button></div>; }) : <p className="text-sm text-muted-foreground">Aún no hay objetivos archivados.</p>}</div> : null}</section><Dialog open={!!editing} onOpenChange={open => !open && setEditing(null)}><DialogContent className="max-h-[90vh] max-w-2xl overflow-y-auto"><DialogHeader><DialogTitle>Editar objetivo</DialogTitle><DialogDescription>Edita el saldo manual y la aportación mensual. Los movimientos registrados se conservan y no se duplican.</DialogDescription></DialogHeader>{editing ? <GoalForm goal={editing} currency={currency} entities={snapshot.entities ?? []} projects={snapshot.projects ?? []} onDone={async () => { await utils.finance.dashboard.invalidate(); setEditing(null); }} /> : null}</DialogContent></Dialog></section>;
}

function DebtsPanel({ snapshot, currency, onCreate }: { snapshot: any; currency: string; onCreate: () => void }) {
  const utils = trpc.useUtils();
  const remove = trpc.finance.debts.remove.useMutation({ onSuccess: () => window.location.reload(), onError: error => toast.error(error.message) });
  const [editingDebt, setEditingDebt] = useState<any | null>(null);
  const debts = snapshot.debts.filter((debt: any) => debt.status !== "paid");
  return <section className="content-card">{debts.length === 0 ? <PlanningEmpty icon={WalletCards} title="Sin deudas activas" text="Registra cualquier obligación relevante para incorporar sus vencimientos y coste estimado a tus revisiones." actionLabel="Añadir deuda" onAction={onCreate} /> : <div className="debt-list">{debts.map((debt: any) => { const monthlyInterest = debt.interestRateBps ? (debt.balanceCents * debt.interestRateBps) / 120000 : null; return <article key={debt.id} className="debt-row"><div className={`debt-priority priority-${debt.priority}`} /><div className="debt-main"><div><span className={`scope-pill scope-${debt.scope}`}>{scopeLabel[debt.scope]}</span><h2>{debt.name}</h2><p>{debt.creditor || "Acreedor pendiente"} · {debtKindLabel(debt.type, debt.loanKind)}</p></div><div className="debt-amount"><strong>{formatMoney(debt.balanceCents, debt.currency)}</strong><small>Saldo actual</small></div></div><div className="debt-meta"><span><small>Tasa anual</small><strong>{debt.interestRateBps === null ? "Sin confirmar" : `${(debt.interestRateBps / 100).toFixed(2)}%`}</strong></span><span><small>Cuota mínima</small><strong>{formatMoney(debt.minimumPaymentCents, debt.currency)}</strong></span><span><small>Interés mensual estimado</small><strong>{monthlyInterest === null ? "—" : formatMoney(Math.round(monthlyInterest), debt.currency)}</strong></span><span><small>Próximo vencimiento</small><strong>{debt.nextDueAt ? formatDate(debt.nextDueAt) : "Pendiente"}</strong></span></div><div className="debt-foot"><p>{debt.notes || "Completa condiciones y documentos para analizar alternativas de forma trazable."}</p><div className="flex items-center gap-1"><Button type="button" size="sm" variant="outline" onClick={() => setEditingDebt(debt)}><Pencil className="mr-1.5 size-3.5" />Editar amortización</Button><button className="row-action-danger" aria-label="Eliminar deuda" onClick={() => { if (confirm("¿Eliminar esta deuda?") ) remove.mutate({ id: debt.id }); }}><Trash2 className="size-4" /></button></div></div></article>; })}</div>}<Dialog open={!!editingDebt} onOpenChange={open => !open && setEditingDebt(null)}><DialogContent className="max-h-[90vh] max-w-2xl overflow-y-auto"><DialogHeader><DialogTitle>Editar amortización</DialogTitle><DialogDescription>Actualiza los parámetros base de la obligación. Los pagos y gastos vinculados se conservan; no se registra ningún pago desde este formulario.</DialogDescription></DialogHeader>{editingDebt ? <DebtForm debt={editingDebt} currency={editingDebt.currency ?? currency} entities={snapshot.entities ?? []} projects={snapshot.projects ?? []} onDone={async () => { await utils.finance.dashboard.invalidate(); setEditingDebt(null); }} /> : null}</DialogContent></Dialog></section>;
}

function TasksPanel({ snapshot, onCreate, refresh }: { snapshot: any; onCreate: () => void; refresh: () => void }) {
  const update = trpc.finance.tasks.save.useMutation({ onSuccess: () => { toast.success("Tarea actualizada"); refresh(); }, onError: error => toast.error(error.message) });
  const remove = trpc.finance.tasks.remove.useMutation({ onSuccess: refresh, onError: error => toast.error(error.message) });
  const items = snapshot.tasks.slice().sort((a: any, b: any) => (a.dueAt ? new Date(a.dueAt).getTime() : Infinity) - (b.dueAt ? new Date(b.dueAt).getTime() : Infinity));
  const complete = (task: any) => update.mutate({ id: task.id, title: task.title, area: task.area, scope: task.scope, priority: task.priority, status: "completed", dueAt: task.dueAt ? new Date(task.dueAt).getTime() : null, goalId: task.goalId, debtId: task.debtId, requiresConfirmation: task.requiresConfirmation, notes: task.notes });
  return <section className="content-card">{items.length === 0 ? <PlanningEmpty icon={ListTodo} title="No hay tareas financieras" text="Crea una próxima acción concreta con una fecha y prioridad. Meximoney no ejecutará ninguna operación por ti." actionLabel="Crear tarea" onAction={onCreate} /> : <div className="task-list task-list-large">{items.map((task: any) => <article className={`task-row task-row-large ${task.status === "completed" ? "task-completed" : ""}`} key={task.id}><button className="task-check" aria-label="Marcar tarea completada" onClick={() => complete(task)} disabled={task.status === "completed"}>{task.status === "completed" ? <Check className="size-4" /> : null}</button><span className={`priority-dot priority-${task.priority}`} /><div><strong>{task.title}</strong><small>{task.dueAt ? `Vence ${formatDate(task.dueAt)}` : "Sin fecha"} · {scopeLabel[task.scope]} · {task.requiresConfirmation ? "Requiere confirmación" : "Seguimiento"}</small>{task.notes ? <p>{task.notes}</p> : null}</div><span className="task-priority">{priorityLabel[task.priority]}</span><button className="row-action-danger" aria-label="Eliminar tarea" onClick={() => { if (confirm("¿Eliminar esta tarea?") ) remove.mutate({ id: task.id }); }}><Trash2 className="size-4" /></button></article>)}</div>}</section>;
}

function ReviewsPanel({ snapshot, currency, onCreate }: { snapshot: any; currency: string; onCreate: () => void }) {
  const reviews = snapshot.reviews.slice().sort((a: any, b: any) => new Date(b.periodStart).getTime() - new Date(a.periodStart).getTime());
  return <section className="content-card">{reviews.length === 0 ? <PlanningEmpty icon={CalendarCheck2} title="Aún no hay revisiones mensuales" text="Al cierre del mes, registra resultados, aprendizajes y tus tres siguientes acciones." actionLabel="Crear primera revisión" onAction={onCreate} /> : <div className="review-list">{reviews.map((review: any) => <article className="review-row" key={review.id}><div className="review-period"><CalendarCheck2 className="size-5" /><div><strong className="capitalize">{formatDate(review.periodStart, { month: "long", year: "numeric" })}</strong><small>{review.status === "closed" ? "Cierre completado" : review.status === "reviewed" ? "Revisada" : "Borrador"}</small></div></div><div><small>Ingresos</small><strong>{formatMoney(review.incomeCents, currency)}</strong></div><div><small>Gastos</small><strong>{formatMoney(review.expenseCents, currency)}</strong></div><div><small>Flujo neto</small><strong className={review.netCashFlowCents >= 0 ? "amount-positive" : "amount-negative"}>{formatMoney(review.netCashFlowCents, currency)}</strong></div><ChevronRight className="size-4 text-muted-foreground" /></article>)}</div>}</section>;
}

function DecisionsPanel({ snapshot, onCreate }: { snapshot: any; onCreate: () => void }) {
  const remove = trpc.finance.decisions.remove.useMutation({ onSuccess: () => window.location.reload(), onError: error => toast.error(error.message) });
  return <section className="decision-grid">{snapshot.decisions.length === 0 ? <section className="content-card"><PlanningEmpty icon={Scale} title="Sin decisiones registradas" text="Documenta el motivo, datos utilizados, hipótesis, riesgos, alternativas y fecha de revisión de las decisiones relevantes." actionLabel="Registrar decisión" onAction={onCreate} /></section> : snapshot.decisions.map((decision: any) => <article className="decision-card" key={decision.id}><div className="card-title-row"><div><span className="decision-status">{decision.status === "approved" ? "Aprobada" : decision.status === "proposal" ? "Propuesta" : decision.status === "reviewed" ? "Revisada" : "Descartada"}</span><h2>{decision.title}</h2><p>{decision.area} · {formatDate(decision.createdAt)}</p></div><button className="row-action-danger" aria-label="Eliminar decisión" onClick={() => { if (confirm("¿Eliminar esta decisión?") ) remove.mutate({ id: decision.id }); }}><Trash2 className="size-4" /></button></div><div className="decision-detail"><strong>Datos usados</strong><p>{decision.dataUsed || "Pendiente de documentar"}</p></div><div className="decision-detail"><strong>Supuestos y riesgos</strong><p>{decision.assumptions || "Sin supuestos registrados"}{decision.risks ? ` · Riesgos: ${decision.risks}` : ""}</p></div><div className="decision-detail"><strong>Alternativas</strong><p>{decision.alternatives || "Sin alternativas registradas"}</p></div><div className="decision-detail"><strong>Revisión</strong><p>{decision.reviewAt ? formatDate(decision.reviewAt) : "Fecha de revisión pendiente"}</p></div></article>)}</section>;
}

function EntityProjectFields({ form, setForm, entities, projects }: { form: any; setForm: (value: any) => void; entities: any[]; projects: any[] }) { const availableProjects = projects.filter(project => !form.entityId || project.entityId === Number(form.entityId)); return <><div className="form-field"><Label>Entidad</Label><select value={form.entityId} onChange={event => setForm({ ...form, entityId: event.target.value, projectId: "" })}><option value="">Sin entidad / personal</option>{entities.map(entity => <option key={entity.id} value={entity.id}>{entity.shortCode || entity.name}</option>)}</select></div><div className="form-field"><Label>Proyecto</Label><select value={form.projectId} onChange={event => setForm({ ...form, projectId: event.target.value })}><option value="">Sin proyecto</option>{availableProjects.map(project => <option key={project.id} value={project.id}>{project.name}</option>)}</select></div></>; }

function BudgetForm({ budget, categories, entities, projects, onDone }: { budget?: any; categories: any[]; entities: any[]; projects: any[]; onDone: () => void | Promise<void> }) {
  const mutation = trpc.finance.budgets.save.useMutation({ onSuccess: async () => { toast.success(budget ? "Partida presupuestaria actualizada" : "Partida presupuestaria creada"); await onDone(); }, onError: error => toast.error(error.message) });
  const [form, setForm] = useState(() => budget ? { categoryId: budget.categoryId?.toString() ?? "", scope: budget.scope, type: budget.type, entityId: budget.entityId?.toString() ?? "", projectId: budget.projectId?.toString() ?? "", planned: fromCents(budget.plannedCents), period: new Date(budget.periodStart).toISOString().slice(0, 7), notes: budget.notes ?? "" } : { categoryId: "", scope: "personal", type: "expense", entityId: "", projectId: "", planned: "", period: new Date().toISOString().slice(0, 7), notes: "" });
  const submit = (event: FormEvent) => { event.preventDefault(); mutation.mutate({ id: budget?.id, entityId: form.entityId ? Number(form.entityId) : null, projectId: form.projectId ? Number(form.projectId) : null, categoryId: form.categoryId ? Number(form.categoryId) : null, scope: form.scope as any, type: form.type as any, plannedCents: toCents(form.planned), periodStart: new Date(`${form.period}-01T12:00:00`).getTime(), notes: form.notes || null }); };
  const categoryApplies = form.type === "income" || form.type === "expense";
  return <form className="form-grid" onSubmit={submit}><div className="form-field"><Label>Periodo</Label><Input type="month" required value={form.period} onChange={event => setForm({ ...form, period: event.target.value })} /></div><div className="form-field"><Label>Tipo</Label><select value={form.type} onChange={event => { const type = event.target.value; setForm({ ...form, type, categoryId: type === "income" || type === "expense" ? form.categoryId : "" }); }}><option value="expense">Gasto</option><option value="income">Ingreso</option><option value="savings">Ahorro</option><option value="investment">Inversión</option></select></div>{categoryApplies ? <div className="form-field"><Label>Categoría</Label><select value={form.categoryId} onChange={event => setForm({ ...form, categoryId: event.target.value })}><option value="">Sin categoría</option>{categories.filter(category => category.isActive).map(category => <option key={category.id} value={category.id}>{category.name}</option>)}</select></div> : <div className="form-field"><Label>Origen del importe real</Label><div className="rounded-md border bg-muted/30 px-3 py-2 text-sm text-muted-foreground">Se calcula desde aportaciones manuales a posiciones de {form.type === "savings" ? "ahorro" : "inversión"}.</div></div>}<div className="form-field"><Label>Área</Label><select value={form.scope} onChange={event => setForm({ ...form, scope: event.target.value })}><option value="personal">Personal</option><option value="business">Empresarial</option><option value="mixed">Mixto</option></select></div><EntityProjectFields form={form} setForm={setForm} entities={entities} projects={projects} /><div className="form-field span-2"><Label>Importe previsto</Label><Input type="number" min="0" step="0.01" required value={form.planned} onChange={event => setForm({ ...form, planned: event.target.value })} /></div><div className="form-field span-2"><Label>Nota</Label><Textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} /></div><div className="form-actions span-2"><Button type="submit" disabled={mutation.isPending}>{mutation.isPending ? "Guardando…" : budget ? "Guardar cambios" : "Guardar partida"}</Button></div></form>;
}

function GoalForm({ goal, currency, entities, projects, onDone }: { goal?: any; currency: string; entities: any[]; projects: any[]; onDone: () => void | Promise<void> }) {
  const mutation = trpc.finance.goals.save.useMutation({ onSuccess: async () => { toast.success(goal ? "Objetivo actualizado" : "Objetivo creado"); await onDone(); }, onError: error => toast.error(error.message) });
  const [form, setForm] = useState(() => goal ? { name: goal.name, type: goal.type, scope: goal.scope, entityId: goal.entityId?.toString() ?? "", projectId: goal.projectId?.toString() ?? "", target: fromCents(goal.targetCents), current: fromCents(goal.currentCents), contribution: fromCents(goal.monthlyContributionCents), currency: goal.currency, targetDate: goal.targetDate ? new Date(goal.targetDate).toISOString().slice(0, 10) : "", priority: goal.priority, notes: goal.notes ?? "" } : { name: "", type: "emergency", scope: "personal", entityId: "", projectId: "", target: "", current: "0", contribution: "0", currency, targetDate: "", priority: "medium", notes: "" });
  const submit = (event: FormEvent) => { event.preventDefault(); mutation.mutate({ id: goal?.id, entityId: form.entityId ? Number(form.entityId) : null, projectId: form.projectId ? Number(form.projectId) : null, name: form.name, type: form.type as any, scope: form.scope as any, targetCents: toCents(form.target), currentCents: toCents(form.current), monthlyContributionCents: toCents(form.contribution), currency: form.currency.toUpperCase(), targetDate: form.targetDate ? new Date(`${form.targetDate}T12:00:00`).getTime() : null, priority: form.priority as any, status: goal?.status ?? "active", notes: form.notes || null }); };
  return <form className="form-grid" onSubmit={submit}><div className="form-field span-2"><Label>Nombre del objetivo</Label><Input required placeholder="Ej. Fondo de emergencia" value={form.name} onChange={event => setForm({ ...form, name: event.target.value })} /></div><div className="form-field"><Label>Tipo</Label><select value={form.type} onChange={event => setForm({ ...form, type: event.target.value })}><option value="emergency">Emergencia</option><option value="debt">Amortizar deuda</option><option value="housing">Vivienda</option><option value="retirement">Jubilación</option><option value="investment">Inversión</option><option value="education">Educación</option><option value="business">Negocio</option><option value="other">Otro</option></select></div><div className="form-field"><Label>Área</Label><select value={form.scope} onChange={event => setForm({ ...form, scope: event.target.value })}><option value="personal">Personal</option><option value="business">Empresarial</option><option value="mixed">Mixto</option></select></div><EntityProjectFields form={form} setForm={setForm} entities={entities} projects={projects} /><div className="form-field"><Label>Moneda</Label><Input required maxLength={3} value={form.currency} onChange={event => setForm({ ...form, currency: event.target.value.toUpperCase() })} /></div><div className="form-field"><Label>Importe objetivo</Label><Input type="number" min="0.01" step="0.01" required value={form.target} onChange={event => setForm({ ...form, target: event.target.value })} /></div><div className="form-field"><Label>Saldo manual</Label><Input type="number" min="0" step="0.01" value={form.current} onChange={event => setForm({ ...form, current: event.target.value })} /><small>No incluye el valor de posiciones vinculadas.</small></div><div className="form-field"><Label>Aportación mensual</Label><Input type="number" min="0" step="0.01" value={form.contribution} onChange={event => setForm({ ...form, contribution: event.target.value })} /></div><div className="form-field"><Label>Fecha objetivo</Label><Input type="date" value={form.targetDate} onChange={event => setForm({ ...form, targetDate: event.target.value })} /></div><div className="form-field"><Label>Prioridad</Label><select value={form.priority} onChange={event => setForm({ ...form, priority: event.target.value })}><option value="critical">Crítica</option><option value="high">Alta</option><option value="medium">Media</option><option value="low">Baja</option></select></div><div className="form-field span-2"><Label>Supuestos o riesgos</Label><Textarea placeholder="Ej. Aportación solo si los ingresos se mantienen" value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} /></div><div className="form-actions span-2"><Button type="submit" disabled={mutation.isPending}>{mutation.isPending ? "Guardando…" : goal ? "Guardar cambios" : "Guardar objetivo"}</Button></div></form>;
}

function DebtForm({ debt, currency, entities, projects, onDone }: { debt?: any; currency: string; entities: any[]; projects: any[]; onDone: () => void }) {
  const mutation = trpc.finance.debts.save.useMutation({ onSuccess: () => { toast.success(debt ? "Amortización actualizada" : "Deuda guardada"); onDone(); }, onError: error => toast.error(error.message) });
  const [form, setForm] = useState(() => debt ? { name: debt.name, creditor: debt.creditor ?? "", type: debt.type, loanKind: debt.loanKind ?? "personal", scope: debt.scope, entityId: debt.entityId?.toString() ?? "", projectId: debt.projectId?.toString() ?? "", balance: fromCents(debt.balanceCents), original: debt.originalAmountCents == null ? "" : fromCents(debt.originalAmountCents), installment: debt.installmentCents == null ? "" : fromCents(debt.installmentCents), installmentCount: debt.installmentCount?.toString() ?? "", financedItem: debt.financedItem ?? "", purchasedAt: debt.purchasedAt ? new Date(debt.purchasedAt).toISOString().slice(0, 10) : "", rate: debt.interestRateBps == null ? "" : (debt.interestRateBps / 100).toFixed(2), minimum: fromCents(debt.minimumPaymentCents), nextDue: debt.nextDueAt ? new Date(debt.nextDueAt).toISOString().slice(0, 10) : "", endDate: debt.endDate ? new Date(debt.endDate).toISOString().slice(0, 10) : "", priority: debt.priority, notes: debt.notes ?? "" } : { name: "", creditor: "", type: "loan", loanKind: "personal", scope: "personal", entityId: "", projectId: "", balance: "", original: "", installment: "", installmentCount: "", financedItem: "", purchasedAt: "", rate: "", minimum: "0", nextDue: "", endDate: "", priority: "medium", notes: "" });
  const isFinancedPurchase = form.type === "financed_purchase";
  const isBankLoan = form.type === "loan" || form.type === "mortgage";
  const submit = (event: FormEvent) => { event.preventDefault(); mutation.mutate({ id: debt?.id, entityId: form.entityId ? Number(form.entityId) : null, projectId: form.projectId ? Number(form.projectId) : null, name: form.name, creditor: form.creditor || null, type: form.type as any, loanKind: (form.type === "mortgage" ? "mortgage" : isBankLoan ? form.loanKind : "not_specified") as any, scope: form.scope as any, balanceCents: toCents(form.balance), originalAmountCents: isFinancedPurchase && form.original ? toCents(form.original) : null, installmentCents: isFinancedPurchase && form.installment ? toCents(form.installment) : null, installmentCount: isFinancedPurchase && form.installmentCount ? Number(form.installmentCount) : null, financedItem: isFinancedPurchase ? form.financedItem || null : null, purchasedAt: isFinancedPurchase && form.purchasedAt ? new Date(`${form.purchasedAt}T12:00:00`).getTime() : null, currency, interestRateBps: form.rate ? Math.round(Number(form.rate) * 100) : null, minimumPaymentCents: toCents(isFinancedPurchase && form.installment ? form.installment : form.minimum), nextDueAt: form.nextDue ? new Date(`${form.nextDue}T12:00:00`).getTime() : null, endDate: form.endDate ? new Date(`${form.endDate}T12:00:00`).getTime() : null, priority: form.priority as any, status: debt?.status ?? "active", notes: form.notes || null }); };
  return <form className="form-grid" onSubmit={submit}><div className="form-field span-2"><Label>Nombre</Label><Input required placeholder={isFinancedPurchase ? "Ej. Moto a mensualidades" : form.type === "mortgage" ? "Ej. Crédito hipotecario" : form.loanKind === "automotive" ? "Ej. Crédito automotriz" : "Ej. Préstamo personal"} value={form.name} onChange={event => setForm({ ...form, name: event.target.value })} /></div><div className="form-field"><Label>Acreedor o tienda</Label><Input value={form.creditor} onChange={event => setForm({ ...form, creditor: event.target.value })} /></div><div className="form-field"><Label>Tipo</Label><select value={form.type} onChange={event => { const type = event.target.value; setForm({ ...form, type, loanKind: type === "mortgage" ? "mortgage" : type === "loan" && form.loanKind === "mortgage" ? "personal" : form.loanKind }); }}><option value="financed_purchase">Compra financiada</option><option value="loan">Préstamo bancario</option><option value="mortgage">Préstamo hipotecario</option><option value="credit_card">Tarjeta departamental (saldo de deuda)</option><option value="tax">Fiscal</option><option value="business">Empresarial</option><option value="family">Familiar</option><option value="other">Otro</option></select></div>{isBankLoan ? <div className="form-field"><Label>Clase de préstamo</Label><select value={form.type === "mortgage" ? "mortgage" : form.loanKind} disabled={form.type === "mortgage"} onChange={event => setForm({ ...form, loanKind: event.target.value })}><option value="personal">Personal</option><option value="automotive">Automotriz</option><option value="mortgage">Hipotecario</option><option value="not_specified">Sin especificar</option></select><small>Etiqueta manual para organizar la obligación; no calcula la amortización.</small></div> : null}{isFinancedPurchase ? <><div className="form-field"><Label>Bien adquirido</Label><Input required placeholder="Ej. Lavadora, freidora, moto" value={form.financedItem} onChange={event => setForm({ ...form, financedItem: event.target.value })} /></div><div className="form-field"><Label>Fecha de compra</Label><Input type="date" value={form.purchasedAt} onChange={event => setForm({ ...form, purchasedAt: event.target.value })} /></div><div className="form-field"><Label>Importe original</Label><Input type="number" min="0" step="0.01" value={form.original} onChange={event => setForm({ ...form, original: event.target.value })} /></div><div className="form-field"><Label>Mensualidad estimada</Label><Input type="number" min="0" step="0.01" value={form.installment} onChange={event => setForm({ ...form, installment: event.target.value })} /></div><div className="form-field"><Label>Número de mensualidades</Label><Input type="number" min="1" step="1" value={form.installmentCount} onChange={event => setForm({ ...form, installmentCount: event.target.value })} /></div></> : null}<div className="form-field"><Label>Saldo pendiente actual</Label><Input type="number" min="0" step="0.01" required value={form.balance} onChange={event => setForm({ ...form, balance: event.target.value })} /></div><div className="form-field"><Label>Tasa anual (%)</Label><Input type="number" min="0" step="0.01" value={form.rate} onChange={event => setForm({ ...form, rate: event.target.value })} /></div><div className="form-field"><Label>{isFinancedPurchase ? "Pago mensual de referencia" : "Cuota mínima"}</Label><Input type="number" min="0" step="0.01" value={isFinancedPurchase ? form.installment : form.minimum} onChange={event => setForm({ ...form, [isFinancedPurchase ? "installment" : "minimum"]: event.target.value })} /></div><div className="form-field"><Label>Próximo vencimiento</Label><Input type="date" value={form.nextDue} onChange={event => setForm({ ...form, nextDue: event.target.value })} /></div><div className="form-field"><Label>Área</Label><select value={form.scope} onChange={event => setForm({ ...form, scope: event.target.value })}><option value="personal">Personal</option><option value="business">Empresarial</option><option value="mixed">Mixto</option></select></div><EntityProjectFields form={form} setForm={setForm} entities={entities} projects={projects} /><div className="form-field"><Label>Prioridad</Label><select value={form.priority} onChange={event => setForm({ ...form, priority: event.target.value })}><option value="critical">Crítica</option><option value="high">Alta</option><option value="medium">Media</option><option value="low">Baja</option></select></div><div className="form-field span-2"><Label>Notas y condiciones</Label><Textarea placeholder="Interés, tienda, seguro, comisión u otra condición relevante" value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} /></div><div className="form-actions span-2"><Button type="submit" disabled={mutation.isPending}>{mutation.isPending ? "Guardando…" : debt ? "Guardar cambios" : "Guardar deuda"}</Button></div></form>;
}

function DebtInstallmentPanel({ snapshot }: { snapshot: any }) {
  const utils = trpc.useUtils();
  const [payingDebt, setPayingDebt] = useState<any | null>(null);
  const [amortizationDebt, setAmortizationDebt] = useState<any | null>(null);
  const removePayment = trpc.finance.debts.paymentRemove.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); toast.success("Cuota desvinculada; el gasto real se conserva"); }, onError: error => toast.error(error.message) });
  const debts = snapshot.debts.filter((debt: any) => debt.status !== "paid");
  const payments = snapshot.debtPayments ?? [];
  return <section className="content-card space-y-4"><div className="rounded-xl border border-primary/15 bg-primary/5 p-4 text-sm text-muted-foreground"><strong className="text-foreground">Cuotas y patrimonio:</strong> registra primero el gasto real desde la cuenta correspondiente en Registros. Aquí vinculas esa cuota y separas capital, interés ordinario, interés vencido y cargos; sólo el capital reduce el saldo pendiente.</div>{debts.map((debt: any) => { const debtPayments = payments.filter((payment: any) => payment.debtId === debt.id).sort((a: any, b: any) => new Date(b.paidAt).getTime() - new Date(a.paidAt).getTime()); return <article className="rounded-xl border p-4" key={debt.id}><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><h3 className="font-semibold">{debt.name}</h3><p className="mt-1 text-sm text-muted-foreground">{debt.type === "financed_purchase" ? `Compra financiada${debt.financedItem ? ` · Bien: ${debt.financedItem}` : ""}` : debtKindLabel(debt.type, debt.loanKind)} · Saldo pendiente: {formatMoney(debt.balanceCents, debt.currency)}</p>{debt.type === "financed_purchase" ? <p className="mt-1 text-xs text-muted-foreground">Original: {debt.originalAmountCents === null ? "pendiente" : formatMoney(debt.originalAmountCents, debt.currency)} · Mensualidad: {debt.installmentCents === null ? "pendiente" : formatMoney(debt.installmentCents, debt.currency)} · {debt.installmentCount ? `${debt.installmentCount} cuotas` : "plazo pendiente"}</p> : null}</div><div className="flex flex-wrap gap-2"><Button type="button" size="sm" variant="outline" onClick={() => setAmortizationDebt(debt)}>Ver amortización</Button><Button type="button" size="sm" variant="outline" onClick={() => setPayingDebt(debt)}>Registrar cuota</Button></div></div>{debtPayments.length ? <div className="mt-4 space-y-2 border-t pt-3">{debtPayments.slice(0, 5).map((payment: any) => <div className="flex flex-wrap items-center justify-between gap-2 text-sm" key={payment.id}><span>{formatDate(payment.paidAt)} · pago {formatMoney(payment.totalPaymentCents, debt.currency)} · capital {formatMoney(payment.principalCents, debt.currency)} · intereses {formatMoney((payment.interestCents ?? 0) + (payment.lateInterestCents ?? 0), debt.currency)}</span><Button type="button" size="sm" variant="ghost" className="text-destructive" onClick={() => { if (confirm("¿Desvincular esta cuota? El gasto original permanecerá intacto.")) removePayment.mutate({ id: payment.id }); }}>Desvincular</Button></div>)}</div> : <p className="mt-3 text-sm text-muted-foreground">Aún no hay cuotas vinculadas.</p>}</article>; })}<Dialog open={!!payingDebt} onOpenChange={open => !open && setPayingDebt(null)}><DialogContent className="max-h-[90vh] max-w-2xl overflow-y-auto"><DialogHeader><DialogTitle>Registrar cuota de {payingDebt?.name}</DialogTitle><DialogDescription>Selecciona el gasto real ya aprobado y registrado desde una cuenta. Sólo el principal reducirá el saldo de la deuda.</DialogDescription></DialogHeader>{payingDebt ? <DebtPaymentForm debt={payingDebt} transactions={snapshot.transactions} onDone={async () => { await utils.finance.dashboard.invalidate(); setPayingDebt(null); }} /> : null}</DialogContent></Dialog><Dialog open={!!amortizationDebt} onOpenChange={open => !open && setAmortizationDebt(null)}>{amortizationDebt ? <PlanningDebtAmortizationDialog debt={amortizationDebt} onChanged={async () => { await utils.finance.dashboard.invalidate(); }} /> : null}</Dialog></section>;
}

function DebtPaymentForm({ debt, transactions, onDone }: { debt: any; transactions: any[]; onDone: () => void | Promise<void> }) {
  const mutation = trpc.finance.debts.paymentSave.useMutation({ onSuccess: async () => { toast.success("Cuota registrada y saldo actualizado"); await onDone(); }, onError: error => toast.error(error.message) });
  const eligibleExpenses = transactions.filter((transaction: any) => transaction.type === "expense" && transaction.accountId && transaction.currency === debt.currency && transaction.reviewStatus === "approved").sort((left: any, right: any) => new Date(right.occurredAt).getTime() - new Date(left.occurredAt).getTime());
  const [form, setForm] = useState({ transactionId: "", total: "", principal: "", interest: "0", lateInterest: "0", fee: "0", paidAt: new Date().toISOString().slice(0, 10), nextDue: debt.nextDueAt ? new Date(debt.nextDueAt).toISOString().slice(0, 10) : "", notes: "" });
  const selectExpense = (id: string) => { const selected = eligibleExpenses.find((item: any) => item.id === Number(id)); setForm({ ...form, transactionId: id, total: selected ? fromCents(selected.amountCents) : form.total, principal: selected ? fromCents(selected.amountCents) : form.principal, interest: "0", lateInterest: "0", fee: "0" }); };
  const componentTotal = toCents(form.principal) + toCents(form.interest) + toCents(form.lateInterest) + toCents(form.fee);
  const submit = (event: FormEvent) => { event.preventDefault(); mutation.mutate({ debtId: debt.id, linkedTransactionId: form.transactionId ? Number(form.transactionId) : null, totalPaymentCents: toCents(form.total), principalCents: toCents(form.principal), interestCents: toCents(form.interest), lateInterestCents: toCents(form.lateInterest), feeCents: toCents(form.fee), currency: debt.currency, paidAt: new Date(`${form.paidAt}T12:00:00`).getTime(), nextDueAt: form.nextDue ? new Date(`${form.nextDue}T12:00:00`).getTime() : null, notes: form.notes || null }); };
  return <form className="form-grid" onSubmit={submit}><div className="form-field span-2"><Label>Gasto real desde cuenta</Label><select required value={form.transactionId} onChange={event => selectExpense(event.target.value)}><option value="">Selecciona la cuota ya registrada desde una cuenta</option>{eligibleExpenses.map((transaction: any) => <option key={transaction.id} value={transaction.id}>{formatDate(transaction.occurredAt)} · {transaction.notes || "Gasto sin nota"} · {formatMoney(transaction.amountCents, debt.currency)}</option>)}</select><p className="text-xs text-muted-foreground">Sólo aparecen gastos aprobados con cuenta y en la moneda de la deuda. Esta operación no crea un segundo gasto.</p></div><div className="form-field"><Label>Pago total</Label><Input type="number" min="0.01" step="0.01" required value={form.total} onChange={event => setForm({ ...form, total: event.target.value })} /></div><div className="form-field"><Label>Capital</Label><Input type="number" min="0" step="0.01" required value={form.principal} onChange={event => setForm({ ...form, principal: event.target.value })} /></div><div className="form-field"><Label>Interés ordinario</Label><Input type="number" min="0" step="0.01" required value={form.interest} onChange={event => setForm({ ...form, interest: event.target.value })} /></div><div className="form-field"><Label>Interés vencido</Label><Input type="number" min="0" step="0.01" required value={form.lateInterest} onChange={event => setForm({ ...form, lateInterest: event.target.value })} /></div><div className="form-field"><Label>Cargos o comisiones</Label><Input type="number" min="0" step="0.01" required value={form.fee} onChange={event => setForm({ ...form, fee: event.target.value })} /></div><div className="form-field"><Label>Desglose capturado</Label><div className={`rounded-md border px-3 py-2 text-sm ${componentTotal === toCents(form.total) ? "border-emerald-200 bg-emerald-50 text-emerald-900" : "border-amber-200 bg-amber-50 text-amber-900"}`}>{formatMoney(componentTotal, debt.currency)}{componentTotal === toCents(form.total) ? " · coincide" : " · debe coincidir con el pago total"}</div></div><div className="form-field"><Label>Fecha de pago</Label><Input type="date" required value={form.paidAt} onChange={event => setForm({ ...form, paidAt: event.target.value })} /></div><div className="form-field"><Label>Siguiente vencimiento</Label><Input type="date" value={form.nextDue} onChange={event => setForm({ ...form, nextDue: event.target.value })} /></div><div className="form-field span-2"><Label>Nota de conciliación</Label><Textarea placeholder="Ej. Cuota de agosto; incluye interés moratorio confirmado" value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} /></div><div className="form-actions span-2"><Button type="submit" disabled={mutation.isPending || componentTotal !== toCents(form.total)}>{mutation.isPending ? "Guardando…" : "Vincular cuota y actualizar saldo"}</Button></div></form>;
}

function LegacyDebtAmortizationDialog({ debt, onChanged }: { debt: any; onChanged: () => void | Promise<void> }) {
  const utils = trpc.useUtils();
  const { data, isLoading } = trpc.finance.debts.amortization.useQuery({ debtId: debt.id });
  const chargeSave = trpc.finance.debts.adjustmentSave.useMutation({ onSuccess: async () => { await utils.finance.debts.amortization.invalidate({ debtId: debt.id }); await onChanged(); toast.success("Cargo manual guardado y saldo actualizado."); }, onError: error => toast.error(error.message) });
  const chargeRemove = trpc.finance.debts.adjustmentRemove.useMutation({ onSuccess: async () => { await utils.finance.debts.amortization.invalidate({ debtId: debt.id }); await onChanged(); toast.success("Cargo manual eliminado."); }, onError: error => toast.error(error.message) });
  const [form, setForm] = useState({ type: "late_interest", amount: "", occurredAt: new Date().toISOString().slice(0, 10), notes: "" });
  const submitCharge = (event: FormEvent) => { event.preventDefault(); chargeSave.mutate({ debtId: debt.id, type: form.type as any, amountCents: toCents(form.amount), currency: debt.currency, occurredAt: new Date(`${form.occurredAt}T12:00:00`).getTime(), notes: form.notes || null }); };
  return <DialogContent className="max-h-[92vh] max-w-5xl overflow-y-auto"><DialogHeader><DialogTitle>Amortización de {debt.name}</DialogTitle><DialogDescription>Historial confirmado y escenario de referencia. La proyección no registra pagos ni intereses automáticamente.</DialogDescription></DialogHeader>{isLoading || !data ? <p className="py-8 text-sm text-muted-foreground">Preparando tabla…</p> : <div className="space-y-5"><div className="rounded-xl border border-primary/15 bg-primary/5 p-3 text-sm text-muted-foreground"><strong className="text-foreground">Saldo actual:</strong> {formatMoney(data.debt.balanceCents, data.debt.currency)}. Los intereses vencidos, cargos y correcciones sólo se reflejan si tú los capturas desde el estado de cuenta o contrato.</div><div className="grid gap-4 lg:grid-cols-2"><section><h3 className="mb-2 text-sm font-semibold">Cuotas conciliadas</h3><div className="overflow-x-auto rounded-xl border"><table className="w-full min-w-[620px] text-sm"><thead className="bg-muted/50 text-left text-xs text-muted-foreground"><tr><th className="p-2">Fecha</th><th className="p-2 text-right">Total</th><th className="p-2 text-right">Capital</th><th className="p-2 text-right">Interés</th><th className="p-2 text-right">Vencido</th><th className="p-2 text-right">Cargos</th></tr></thead><tbody>{data.payments.length ? data.payments.map((item: any) => <tr className="border-t" key={item.id}><td className="p-2">{formatDate(item.paidAt)}</td><td className="p-2 text-right">{formatMoney(item.totalPaymentCents, data.debt.currency)}</td><td className="p-2 text-right">{formatMoney(item.principalCents, data.debt.currency)}</td><td className="p-2 text-right">{formatMoney(item.interestCents, data.debt.currency)}</td><td className="p-2 text-right">{formatMoney(item.lateInterestCents, data.debt.currency)}</td><td className="p-2 text-right">{formatMoney(item.feeCents, data.debt.currency)}</td></tr>) : <tr><td colSpan={6} className="p-5 text-center text-muted-foreground">Sin cuotas conciliadas todavía.</td></tr>}</tbody></table></div></section><section><h3 className="mb-2 text-sm font-semibold">Intereses y cargos manuales</h3><div className="space-y-2">{data.adjustments.length ? data.adjustments.map((item: any) => <div className="flex items-center justify-between gap-3 rounded-lg border p-3 text-sm" key={item.id}><span><strong>{item.type === "late_interest" ? "Interés vencido" : item.type === "finance_charge" ? "Cargo financiero" : item.type === "other_charge" ? "Otro cargo" : "Corrección"}</strong><small className="mt-1 block text-muted-foreground">{formatDate(item.occurredAt)}{item.notes ? ` · ${item.notes}` : ""}</small></span><span className="flex items-center gap-2"><strong>{formatMoney(item.amountCents, data.debt.currency)}</strong><Button type="button" size="icon" variant="ghost" aria-label="Eliminar cargo manual" onClick={() => { if (confirm("¿Eliminar este cargo? Sólo se permite si el saldo sigue siendo coherente.")) chargeRemove.mutate({ id: item.id }); }}><Trash2 className="size-4 text-muted-foreground" /></Button></span></div>) : <p className="rounded-xl border border-dashed p-4 text-sm text-muted-foreground">No hay cargos manuales registrados.</p>}</div><form className="mt-3 grid gap-2 rounded-xl border p-3" onSubmit={submitCharge}><p className="text-sm font-semibold">Registrar cargo confirmado</p><div className="grid gap-2 sm:grid-cols-3"><select value={form.type} onChange={event => setForm({ ...form, type: event.target.value })}><option value="late_interest">Interés vencido</option><option value="finance_charge">Cargo financiero</option><option value="other_charge">Otro cargo</option><option value="correction">Corrección de saldo</option></select><Input required type="number" min={form.type === "correction" ? undefined : "0.01"} step="0.01" placeholder="Importe" value={form.amount} onChange={event => setForm({ ...form, amount: event.target.value })}/><Input required type="date" value={form.occurredAt} onChange={event => setForm({ ...form, occurredAt: event.target.value })}/></div><Textarea placeholder="Referencia del estado de cuenta o contrato" value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })}/><Button type="submit" size="sm" variant="outline" disabled={chargeSave.isPending || !form.amount}>{chargeSave.isPending ? "Guardando…" : "Guardar cargo manual"}</Button></form></section></div><section><div className="mb-2 flex flex-wrap items-end justify-between gap-2"><div><h3 className="text-sm font-semibold">Escenario de amortización</h3><p className="text-xs text-muted-foreground">Usa la tasa y pago mensual de referencia de la deuda. No incluye futuros atrasos ni cargos.</p></div><span className="text-sm font-medium">Interés proyectado: {formatMoney(data.projection.totalProjectedInterestCents, data.debt.currency)}</span></div>{data.projection.warning ? <div className="mb-3 rounded-xl border border-amber-200 bg-amber-50 p-3 text-sm text-amber-950"><AlertTriangle className="mr-2 inline size-4"/>{data.projection.warning}</div> : null}<div className="overflow-x-auto rounded-xl border"><table className="w-full min-w-[640px] text-sm"><thead className="bg-muted/50 text-left text-xs text-muted-foreground"><tr><th className="p-2">Cuota</th><th className="p-2 text-right">Saldo inicial</th><th className="p-2 text-right">Interés ordinario</th><th className="p-2 text-right">Pago ref.</th><th className="p-2 text-right">Capital</th><th className="p-2 text-right">Saldo final</th></tr></thead><tbody>{data.projection.rows.length ? data.projection.rows.map((row: any) => <tr className="border-t" key={row.installment}><td className="p-2">{row.installment}</td><td className="p-2 text-right">{formatMoney(row.openingBalanceCents, data.debt.currency)}</td><td className="p-2 text-right">{formatMoney(row.regularInterestCents, data.debt.currency)}</td><td className="p-2 text-right">{formatMoney(row.plannedPaymentCents, data.debt.currency)}</td><td className="p-2 text-right">{formatMoney(row.principalCents, data.debt.currency)}</td><td className="p-2 text-right">{formatMoney(row.closingBalanceCents, data.debt.currency)}</td></tr>) : <tr><td colSpan={6} className="p-5 text-center text-muted-foreground">Completa el pago mensual de referencia para proyectar cuotas.</td></tr>}</tbody></table></div></section></div>}</DialogContent>;
}

function TaskForm({ goals, debts, onDone }: { goals: any[]; debts: any[]; onDone: () => void }) {
  const mutation = trpc.finance.tasks.save.useMutation({ onSuccess: () => { toast.success("Tarea creada"); onDone(); }, onError: error => toast.error(error.message) });
  const [form, setForm] = useState({ title: "", area: "review", scope: "personal", priority: "medium", dueAt: "", goalId: "", debtId: "", requiresConfirmation: true, notes: "" });
  const submit = (event: FormEvent) => { event.preventDefault(); mutation.mutate({ title: form.title, area: form.area as any, scope: form.scope as any, priority: form.priority as any, status: "pending", dueAt: form.dueAt ? new Date(`${form.dueAt}T12:00:00`).getTime() : null, goalId: form.goalId ? Number(form.goalId) : null, debtId: form.debtId ? Number(form.debtId) : null, requiresConfirmation: form.requiresConfirmation, notes: form.notes || null }); };
  return <form className="form-grid" onSubmit={submit}><div className="form-field span-2"><Label>Acción</Label><Input required placeholder="Ej. Revisar vencimiento de la póliza" value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} /></div><div className="form-field"><Label>Área</Label><select value={form.area} onChange={event => setForm({ ...form, area: event.target.value })}><option value="budget">Presupuesto</option><option value="debt">Deuda</option><option value="savings">Ahorro</option><option value="investment">Inversión</option><option value="tax">Fiscal</option><option value="documents">Documentos</option><option value="business">Negocio</option><option value="review">Revisión</option><option value="other">Otra</option></select></div><div className="form-field"><Label>Fecha límite</Label><Input type="date" value={form.dueAt} onChange={event => setForm({ ...form, dueAt: event.target.value })} /></div><div className="form-field"><Label>Objetivo vinculado</Label><select value={form.goalId} onChange={event => setForm({ ...form, goalId: event.target.value })}><option value="">Sin objetivo</option>{goals.map(goal => <option key={goal.id} value={goal.id}>{goal.name}</option>)}</select></div><div className="form-field"><Label>Deuda vinculada</Label><select value={form.debtId} onChange={event => setForm({ ...form, debtId: event.target.value })}><option value="">Sin deuda</option>{debts.map(debt => <option key={debt.id} value={debt.id}>{debt.name}</option>)}</select></div><div className="form-field"><Label>Prioridad</Label><select value={form.priority} onChange={event => setForm({ ...form, priority: event.target.value })}><option value="critical">Crítica</option><option value="high">Alta</option><option value="medium">Media</option><option value="low">Baja</option></select></div><div className="form-field"><Label>Área financiera</Label><select value={form.scope} onChange={event => setForm({ ...form, scope: event.target.value })}><option value="personal">Personal</option><option value="business">Empresarial</option><option value="mixed">Mixto</option></select></div><div className="form-field span-2"><Label>Notas</Label><Textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} /></div><div className="form-actions span-2"><Button type="submit" disabled={mutation.isPending}>Guardar tarea</Button></div></form>;
}

function ReviewForm({ snapshot, onDone }: { snapshot: any; onDone: () => void }) {
  const mutation = trpc.finance.reviews.save.useMutation({ onSuccess: () => { toast.success("Revisión guardada"); onDone(); }, onError: error => toast.error(error.message) });
  const [form, setForm] = useState({ period: new Date(snapshot.dashboard.periodStart).toISOString().slice(0, 7), status: "draft", observations: "", nextActions: "" });
  const submit = (event: FormEvent) => { event.preventDefault(); mutation.mutate({ periodStart: new Date(`${form.period}-01T12:00:00`).getTime(), status: form.status as any, incomeCents: snapshot.dashboard.cashFlow.incomeCents, expenseCents: snapshot.dashboard.cashFlow.expenseCents, netCashFlowCents: snapshot.dashboard.cashFlow.netCashFlowCents, observations: form.observations || null, nextActions: form.nextActions || null }); };
  return <form className="form-grid" onSubmit={submit}><div className="form-field"><Label>Periodo</Label><Input type="month" value={form.period} onChange={event => setForm({ ...form, period: event.target.value })} /></div><div className="form-field"><Label>Estado</Label><select value={form.status} onChange={event => setForm({ ...form, status: event.target.value })}><option value="draft">Borrador</option><option value="reviewed">Revisada</option><option value="closed">Cerrada</option></select></div><div className="review-preview span-2"><span>Ingresos del periodo</span><strong>{formatMoney(snapshot.dashboard.cashFlow.incomeCents, snapshot.profile?.currency ?? "MXN")}</strong><span>Gastos del periodo</span><strong>{formatMoney(snapshot.dashboard.cashFlow.expenseCents, snapshot.profile?.currency ?? "MXN")}</strong><span>Flujo neto</span><strong>{formatMoney(snapshot.dashboard.cashFlow.netCashFlowCents, snapshot.profile?.currency ?? "MXN")}</strong></div><div className="form-field span-2"><Label>Observaciones</Label><Textarea placeholder="Qué cambió, qué funcionó, qué hay que revisar" value={form.observations} onChange={event => setForm({ ...form, observations: event.target.value })} /></div><div className="form-field span-2"><Label>Próximas acciones</Label><Textarea placeholder="Tres acciones concretas para el siguiente periodo" value={form.nextActions} onChange={event => setForm({ ...form, nextActions: event.target.value })} /></div><div className="form-actions span-2"><Button type="submit" disabled={mutation.isPending}>Guardar revisión</Button></div></form>;
}

function DecisionForm({ onDone }: { onDone: () => void }) {
  const mutation = trpc.finance.decisions.save.useMutation({ onSuccess: () => { toast.success("Decisión registrada"); onDone(); }, onError: error => toast.error(error.message) });
  const [form, setForm] = useState({ title: "", area: "budget", status: "proposal", dataUsed: "", assumptions: "", risks: "", alternatives: "", approvedAction: "", reviewAt: "" });
  const submit = (event: FormEvent) => { event.preventDefault(); mutation.mutate({ ...form, area: form.area as any, status: form.status as any, dataUsed: form.dataUsed || null, assumptions: form.assumptions || null, risks: form.risks || null, alternatives: form.alternatives || null, approvedAction: form.approvedAction || null, reviewAt: form.reviewAt ? new Date(`${form.reviewAt}T12:00:00`).getTime() : null }); };
  return <form className="form-grid" onSubmit={submit}><div className="form-field span-2"><Label>Decisión</Label><Input required placeholder="Ej. Priorizar fondo de emergencia sobre inversión" value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} /></div><div className="form-field"><Label>Área</Label><select value={form.area} onChange={event => setForm({ ...form, area: event.target.value })}><option value="budget">Presupuesto</option><option value="debt">Deuda</option><option value="savings">Ahorro</option><option value="investment">Inversión</option><option value="tax">Fiscal</option><option value="insurance">Seguros</option><option value="assets">Activos</option><option value="other">Otra</option></select></div><div className="form-field"><Label>Estado</Label><select value={form.status} onChange={event => setForm({ ...form, status: event.target.value })}><option value="proposal">Propuesta</option><option value="approved">Aprobada</option><option value="reviewed">Revisada</option><option value="discarded">Descartada</option></select></div><div className="form-field span-2"><Label>Datos utilizados</Label><Textarea placeholder="Periodo, cuentas, movimientos, deudas u objetivos usados" value={form.dataUsed} onChange={event => setForm({ ...form, dataUsed: event.target.value })} /></div><div className="form-field"><Label>Supuestos</Label><Textarea value={form.assumptions} onChange={event => setForm({ ...form, assumptions: event.target.value })} /></div><div className="form-field"><Label>Riesgos</Label><Textarea value={form.risks} onChange={event => setForm({ ...form, risks: event.target.value })} /></div><div className="form-field span-2"><Label>Alternativas consideradas</Label><Textarea value={form.alternatives} onChange={event => setForm({ ...form, alternatives: event.target.value })} /></div><div className="form-field span-2"><Label>Acción aprobada</Label><Textarea value={form.approvedAction} onChange={event => setForm({ ...form, approvedAction: event.target.value })} /></div><div className="form-field"><Label>Fecha de revisión</Label><Input type="date" value={form.reviewAt} onChange={event => setForm({ ...form, reviewAt: event.target.value })} /></div><div className="form-actions span-2"><Button type="submit" disabled={mutation.isPending}>Guardar decisión</Button></div></form>;
}
